bool FieldPayphoneData::load_file(const char*p,std::string&e){if(!p){e="Payphone source path absent";return false;}std::ifstream f(p,std::ios::binary);if(!f){e="Payphone resource unavailable";return false;}f.seekg(0,std::ios::end);auto n=f.tellg();if(n<64||n>4*1024*1024){e="Payphone resource size rejected";return false;}f.seekg(0);std::vector<uint8_t>b(static_cast<size_t>(n));if(!f.read(reinterpret_cast<char*>(b.data()),n)){e="Payphone resource read failed";return false;}return load(b.data(),b.size(),e);}
